195:       // Fetch and fully decode agents before mutating the cache.
196:       const response = await apiService.get<unknown>('/api/agents');
197:       const decoded = decodeListResponse(response, 'agents', decodeAgent);
198: 
199:       if (!decoded.ok) {
200:         console.error('AgentSync: Failed to fetch agents:', decoded.error);
201:         return {
202:           success: false,
203:           synced: 0,
204:           failed: 0,
205:           conflicts: 0,
206:           duration: Date.now() - startTime,
207:         };
208:       }
209: 
210:       const agents = decoded.items;
211: 
212:       // Process each agent
213:       for (const agent of agents) {
214:         try {
215:           const cached = this.cache.agents[agent.id];
216: 
217:           // Check for conflict
218:           if (cached && new Date(agent.updatedAt) < new Date(cached.updatedAt)) {
219:             conflicts++;
220:             await this.queueConflictResolution(agent, cached);
221:             continue;
222:           }
223: 
224:           // Update cache
225:           this.cache.agents[agent.id] = agent;
226:           synced++;
227:         } catch (error) {
228:           console.error(`AgentSync: Failed to sync agent ${agent.id}:`, error);
229:           failed++;
230:         }
231:       }
232: 
233:       // Update cache metadata
234:       this.cache.lastSyncAt = new Date();
235: 
236:       // Save cache
237:       await this.saveCache();
238: 
239:       const duration = Date.now() - startTime;
240:       console.log(`AgentSync: Sync complete - ${synced} synced, ${failed} failed, ${conflicts} conflicts, ${duration}ms`);
241: 
242:       return {
243:         success: true,
244:         synced,
245:         failed,
246:         conflicts,
247:         duration,
248:       };
249:     } catch (error) {
250:       console.error('AgentSync: Sync failed:', error);
251:       return {
252:         success: false,
253:         synced,
254:         failed,
255:         conflicts,
256:         duration: Date.now() - startTime,
257:       };
258:     }
