303:     agentId: string,
304:     updates: Partial<Agent>,
305:     userId: string,
306:     deviceId: string
307:   ): Promise<boolean> {
308:     try {
309:       // Check if offline
310:       const isOffline = !(await this.isOnline());
311: 
312:       if (isOffline) {
313:         // Queue for sync
314:         await offlineSyncService.queueAction(
315:           'agent_sync',
316:           {
317:             agentId,
318:             agentData: updates,
319:           },
320:           'normal',
321:           userId,
322:           deviceId,
323:           'last_write_wins',
324:           'agents',
325:           agentId
326:         );
327: 
328:         // Update local cache optimistically
329:         if (this.cache.agents[agentId]) {
330:           this.cache.agents[agentId] = {
331:             ...this.cache.agents[agentId],
332:             ...updates,
333:             updatedAt: new Date(),
334:           };
335:           await this.saveCache();
336:         }
337: 
338:         return true;
339:       }
340: 
341:       // Sync to server
342:       const response = await apiService.put(`/api/agents/${agentId}`, updates);
343: 
344:       if (response.success) {
345:         // Update cache
346:         if (this.cache.agents[agentId]) {
347:           this.cache.agents[agentId] = {
348:             ...this.cache.agents[agentId],
349:             ...updates,
350:             updatedAt: new Date(),
351:           };
352:           await this.saveCache();
353:         }
354:         return true;
355:       }
356: 
357:       return false;
358:     } catch (error) {
359:       console.error(`AgentSync: Failed to update agent ${agentId}:`, error);
360:       return false;
361:     }
