524:   private async saveCache(): Promise<void> {
525:     // Enforce cache size limit
526:     const agentIds = Object.keys(this.cache.agents);
527:     if (agentIds.length > MAX_CACHE_SIZE) {
528:       // Remove oldest agents
529:       const sorted = agentIds.sort((a, b) => {
530:         const dateA = new Date(this.cache.agents[a].updatedAt).getTime();
531:         const dateB = new Date(this.cache.agents[b].updatedAt).getTime();
532:         return dateA - dateB;
533:       });
534: 
535:       const toRemove = sorted.slice(0, agentIds.length - MAX_CACHE_SIZE);
536:       for (const id of toRemove) {
537:         delete this.cache.agents[id];
538:       }
539:     }
540: 
541:     if (!(await storageService.setObject('agent_cache' as StorageKey, this.cache))) {
542:       throw new Error('Agent cache persistence refused');
543:     }
544:   }
